INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-relato-de-la-cueva-misteriosa', 'El Relato de la Cueva Misteriosa', 'Dinámica nocturna de narración oral y reflejos donde los scouts inventan una historia en círculo al calor de la linterna capturando objetos al escuchar la palabra clave.', '<h2>📜 Descripción de El Relato de la Cueva Misteriosa</h2>
<p><b>El Relato de la Cueva Misteriosa</b> es una dinámica scout de velada o campamento que combina la improvisación narrativa, la atención auditiva y la velocidad de reacción. Los participantes se sientan en círculo dentro de una carpa o espacio a oscuras alrededor de una linterna de campamento y pequeños objetos. Un dirigente o scout inicia un cuento de misterio o leyenda local. Cada vez que el narrador pronuncia la palabra gatillo (ej. <i>''Miedo''</i> o <i>''Cueva''</i>), todos los jugadores deben atrapar inmediatamente un objeto del centro. Quien quede con las manos vacías toma el relevo de la historia.</p>
<p>Esta dinámica desarrolla el sentido del humor, la escucha activa y la soltura escénica en Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega El Relato de la Cueva Misteriosa?</h2>
<p>Para desarrollar la dinámica con fluidez y emoción, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Atmósfera Inicial:</b> Los participantes se sientan en círculo en una carpa o sala a media luz. En el centro se colocan pequeños objetos de campamento (pequeñas piedras suaves, piñas de pino o mosquetones) en una cantidad menor por una unidad respecto al total de participantes.</li>
  <li><b>El Inicio de la Leyenda:</b> El narrador inicial comienza a relatar una historia fantástica o de suspenso inventada en el momento.</li>
  <li><b>El Gatillo Auditivo:</b> En medio de la narración, al pronunciar la palabra clave prefijada (ej. <i>''Miedo''</i>), todos los scouts deben abalanzarse con rapidez a tomar un objeto del montón central.</li>
  <li><b>Toma de Relevo:</b> El participante que no alcance objeto debe continuar la historia desde el punto exacto en que quedó, introduciendo nuevos elementos creativos hasta volver a pronunciar la palabra gatillo.</li>
  <li><b>Conclusión:</b> Todos los objetos se reubican en el centro tras cada susto y la ronda continúa garantizando que todos los participantes intervengan en el relato.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Relato de la Cueva Misteriosa</h2>
<p>La actividad prioriza la distensión y la agilidad de reflejos en el Tally:</p>
<ul>
  <li><b>Mejor Giro Narrativo:</b> Otorgar 5 puntos a la patrulla o seisena del participante que logre la improvisación más divertida o intrigante.</li>
  <li><b>Velocidad de Reacción:</b> Otorgar 3 puntos al scout que demuestre los mejores reflejos auditivos para asegurar su objeto.</li>
  <li><b>Clima Fraterno:</b> Otorgar 3 puntos a la unidad que mantenga la mejor actitud de respeto y apoyo hacia los narradores.</li>
</ul>', '/uploads/el-relato-de-la-cueva-misteriosa.webp', 'publicado', '{"areas": ["carácter", "creatividad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Exterior"], "materiales": ["Linternas", "Objetos Varios"], "objetivos": ["Enfrentar la vida con alegría y sentido del humor", "Estimular la atención auditiva", "Desarrollo de la capacidad de improvisación", "Fomentar la integración del grupo"], "justificacion_areas": "El Relato de la Cueva Misteriosa fortalece el carácter al enseñar a tomar el error con sentido del humor y superar la timidez al hablar en público. Estimula la creatividad a través de la improvisación continua de tramas fantásticas. Desarrolla la sociabilidad al afianzar la escucha respetuosa y la contención afectiva del grupo.", "variaciones": "<b>El Relato bajo el Paracaídas:</b> Montar una cueva artificial con un paracaídas o toldo scout sosteniéndolo en el centro con un báculo.<br><b>Palabras Clave Múltiples:</b> Asignar palabras distintas según la especie de patrulla (ej. si dice ''Bosque'' reaccionan los Lobos, si dice ''Noche'' reaccionan las Águilas).<br><b>Relato con Efectos Sonoros:</b> Exigir que quien toma el relevo acompañe la narración con chasquidos o ruidos de ambiente.", "recomendaciones": "Para las unidades menores (Manada), sustituir las tramas de suspenso por historias de fantasía y aventuras divertidas para evitar generar temor innecesario. Mantener la superficie del centro libre de bordes filosos. Supervisar que el manotazo a los objetos sea suave y prudente.", "objetivos_educativos": [{"id": "eba5dac5-e1aa-498d-8d94-9655162890e5", "area": "Carácter", "unidad": "Manada", "texto": "Entiendo que es bueno que tenga metas que me ayuden a ser cada día mejor.", "como_se_cumple": "Aceptando con sentido del humor y alegría el reto de continuar la historia al quedar con las manos vacías."}, {"id": "feeaf72d-4c33-4edd-8513-000a659d0491", "area": "Carácter", "unidad": "Manada", "texto": "Me propongo tareas y metas que me ayudan a superar mis defectos.", "como_se_cumple": "Superando la inhibición para expresarme con soltura y solidez ante la seisena."}, {"id": "2385386e-34db-4282-9934-7fcc515cb449", "area": "Carácter", "unidad": "Compañía", "texto": "Me propongo metas para ser mejor.", "como_se_cumple": "Desarrollando autoconfianza al improvisar pasajes creativos frente a la patrulla."}, {"id": "672c638b-637e-4518-9dfb-ec92fb03c5cf", "area": "Carácter", "unidad": "Compañía", "texto": "Soy constante en mis propósitos.", "como_se_cumple": "Manteniendo la energía narrativa e hilarante a lo largo de toda la velada."}, {"id": "41386aca-6175-4483-9e3b-54ac85ca5eb9", "area": "Carácter", "unidad": "Tropa", "texto": "Me propongo metas para ser mejor.", "como_se_cumple": "Asumiendo con determinación el liderazgo del relato improvisado."}, {"id": "71413ac6-8ae9-4034-b580-e2f1c2f9f42c", "area": "Carácter", "unidad": "Tropa", "texto": "Me esfuerzo cada vez más en superar mis defectos.", "como_se_cumple": "Venciendo el temor escénico para enriquecer el clima de la Tropa."}, {"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "unidad": "Manada", "texto": "Me gusta participar en juegos de observación.", "como_se_cumple": "Observando el movimiento del narrador para anticipar la palabra clave."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Conectando al instante la trama con nuevos personajes y aventuras."}, {"id": "e1b7276f-4fd2-4c39-a32a-bd7fadbee702", "area": "Creatividad", "unidad": "Compañía", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Expresando ideas y giros argumentales dramáticos e innovadores."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Integrando las sugerencias narrativas del grupo en el desenlace del relato."}, {"id": "49ae6ac6-be8f-4f2c-8b3e-6711d041181f", "area": "Creatividad", "unidad": "Tropa", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Aportando agilidad de improvisación para desenredar el conflicto del cuento."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "unidad": "Tropa", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Analizando las expectativas del auditorio para crear pasajes fascinantes."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando con lealtad las normas de toma de objetos e inmovilidad."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Escuchando en silencio absoluto el turno del narrador de la seisena."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Favoreciendo un ambiente seguro y de respeto al espacio físico de los pares."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Promoviendo el trabajo en equipo y el fair play en las rondas de competencia."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Cumpliendo con honestidad scout la declaración de agarre de objetos."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Construyendo lazos fraternos mediante la convivencia y el humor de campamento."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

